function mapSvg(values){const w=480,h=650,p=18,allLon=snapshot.lon.flat(),allLat=snapshot.lat.flat(),minLon=Math.min(...allLon),maxLon=Math.max(...allLon),minLat=Math.min(...allLat),maxLat=Math.max(...allLat);const x=v=>p+(v-minLon)/(maxLon-minLon)*(w-p*2),y=v=>h-p-(v-minLat)/(maxLat-minLat)*(h-p*2),project=(lo,la)=>`${x(lo)},${y(la)}`;const polys=snapshot.lon.map((tri,i)=>`<polygon class="patch" tabindex="0" data-id="${i}" data-value="${values[i]}" points="${tri.map((lo,j)=>project(lo,snapshot.lat[i][j])).join(" ")}" fill="${color(values[i])}"><title>Patch ${i+1}: ${fmt(values[i])} mm/day</title></polygon>`).join("");const paths=coast.lines.map(line=>`<polyline points="${line.map(([lo,la])=>project(lo,la)).join(" ")}" fill="none"/>`).join("");const lonTicks=[-128,-126,-124,-122].filter(t=>t>minLon&&t<maxLon),latTicks=[40,42,44,46,48,50].filter(t=>t>minLat&&t<maxLat);return `<svg class="fault" viewBox="0 0 ${w} ${h}" role="img" aria-label="Cascadia fault slip velocity map"><rect width="${w}" height="${h}" fill="#eaf1f5"/>${polys}<g class="grid">${lonTicks.map(t=>`<line x1="${x(t)}" x2="${x(t)}" y1="18" y2="632"/>`).join("")}${latTicks.map(t=>`<line x1="18" x2="462" y1="${y(t)}" y2="${y(t)}"/>`).join("")}</g><g class="coast">${paths}</g><g class="labels">${lonTicks.map(t=>`<text x="${x(t)}" y="644" text-anchor="middle">${Math.abs(t)}°W</text>`).join("")}${latTicks.map(t=>`<text x="22" y="${y(t)-4}">${t}°N</text>`).join("")}</g></svg>`}
function render(){const dates=mode==="forecast"?snapshot.forecast_dates:snapshot.input_dates;day=Math.min(day,dates.length-1);const values=(mode==="forecast"?snapshot.forecast_velocity_mm_per_day:snapshot.input_velocity_mm_per_day)[day][component],selected=dates[day];document.querySelector("#app").className="";document.querySelector("#app").innerHTML=`<section class="hero"><div><p class="eyebrow">CASCADIA · DAILY FORECAST</p><h1>SSECast</h1><p class="copy">A deep-learning framework that advances two daily GNSS-derived slip-potency fields to forecast the next 14 days of slow-slip initiation, migration and decay along the Cascadia plate interface.</p></div><div class="meta"><span>Current input</span><b>${snapshot.input_dates[0]} — ${snapshot.input_dates[1]}</b><span>Forecast horizon</span><b>${snapshot.forecast_dates[0]} — ${snapshot.forecast_dates.at(-1)}</b></div></section><section class="workspace"><div class="map-panel"><div class="panel-head"><div><p class="fig">FIG. 01 · CASCADIA SLIP-VELOCITY FIELD</p><h2>${selected}</h2></div><div class="range"><span>−${LIMIT}</span><div class="gradient"></div><span>+${LIMIT}</span><small>mm/day</small></div></div>${mapSvg(values)}<div id="hover" class="footerline">Hover a patch for its value</div></div><aside class="controls"><p class="control-title">VIEW PARAMETERS</p><div class="block"><p class="eyebrow">DISPLAY</p><div class="segment"><button data-mode="input" class="${mode==='input'?'active':''}">Latest inputs</button><button data-mode="forecast" class="${mode==='forecast'?'active':''}">14-day forecast</button></div></div><div class="block"><p class="eyebrow">COMPONENT</p><div class="component">${labels.map((l,i)=>`<button data-component="${i}" class="${i===component?'selected':''}"><i></i>${l}</button>`).join('')}</div></div><div class="block"><p class="eyebrow">${mode==='forecast'?'FORECAST DAY':'INPUT DATE'}</p><div class="dates">${dates.map((d,i)=>`<button data-day="${i}" class="${i===day?'selected':''}"><span>${mode==='forecast'?`D${i+1}`:`Input ${i+1}`}</span><b>${d}</b></button>`).join('')}</div></div></aside></section><section class="delay"><p class="eyebrow">FILTERING DELAY</p><h2>Results are shown with a three-day delay.</h2><p>Filtering used in the inversion adds a three-day delay. All displayed results therefore represent conditions from three days before the displayed date.</p></section><footer>Daily SSECast · Cascadia slow-slip forecast · Snapshot ${new Date(snapshot.generated_at_utc).toUTCString()}</footer>`;bind()}
function bind(){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;day=mode==='input'?1:0;hover=null;render()});document.querySelectorAll('[data-component]').forEach(b=>b.onclick=()=>{component=+b.dataset.component;hover=null;render()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=+b.dataset.day;hover=null;render()});document.querySelectorAll('.patch').forEach(p=>{const show=()=>document.querySelector('#hover').innerHTML=`Patch ${+p.dataset.id+1}: <b>${fmt(+p.dataset.value)} mm/day</b>`;p.onpointerenter=show;p.onfocus=show;p.onpointerleave=()=>document.querySelector('#hover').textContent='Hover a patch for its value';p.onblur=()=>document.querySelector('#hover').textContent='Hover a patch for its value'})}
function load(){render()}
load();
